-- 4) Variants for new products
ON CONFLICT (id) DO NOTHING;

-- 5) Product images (10 products)

-- 6) Inventory levels in default warehouse
SELECT v.store_id, '893eb721-50dc-48d6-be18-eb74f9d2ded5', v.id, v.product_id, v.stock, 0, 3
FROM public.product_variants v
WHERE v.product_id IN (
  '33333333-0000-4000-8000-000000000010','33333333-0000-4000-8000-000000000011',
  '33333333-0000-4000-8000-000000000012','33333333-0000-4000-8000-000000000013',
  '33333333-0000-4000-8000-000000000014','33333333-0000-4000-8000-000000000015')
ON CONFLICT DO NOTHING;

-- 7) Collection membership
SELECT p.id, c.id
FROM public.products p CROSS JOIN public.collections c
WHERE p.id IN ('33333333-0000-4000-8000-000000000010','33333333-0000-4000-8000-000000000011','33333333-0000-4000-8000-000000000014')
  AND c.store_id = '11111111-1111-1111-1111-111111111111'
ON CONFLICT DO NOTHING;

